mapper.select:
SELECT  FROM paiflow_run_checkpoint c JOIN paiflow_run r ON r.id=c.run_id
WHERE c.state IN('WAITING','RESUMED') AND (c.deadline <= #{now} OR r.deadline <= #{now} OR r.lease_expires_at <= #{now}
  OR r.state IN('CANCEL_REQUESTED','COMPLETED','FAILED','CANCELLED','EFFECT_UNKNOWN')) ORDER BY c.create_time,c.id LIMIT #{limit}
